/* =====================================================================
   games/numtrain/controls.js — 数字小列车 · 控制层
   点候选块作答（按下即可，小朋友不用区分按下/抬起）；
   数字键 1~6 = 按顺序选第几块；H = 教我。
   ===================================================================== */

export function createControls() {
  return {
    keys: {
      1: 'p1', 2: 'p2', 3: 'p3', 4: 'p4', 5: 'p5', 6: 'p6',
      h: 'hint'
    },

    pointer(game, p, type) {
      if (type !== 'down') return;
      game.tap(p.x, p.y);
    }
  };
}
